func (p *PodInfo) PodToEtcdServiceEndpoint(containerStatus core.ContainerStatus, podServiceNames []string, healthStatus servicev1.HealthCheckStatus, lrcConfig *nexusmeshv1alpha1.LocalRegistrationConfig) ([]*servicev1.ServiceEndpoint, error) {
	if len(podServiceNames) == 0 && lrcConfig == nil {
		metrics.UpdatePodRegisterStatus(p.Namespace, p.Name, strings.Join(podServiceNames, ","), metrics.PodDoesNotBelongToAnyService)
		return nil, errors.New("pod doesn't belong to any service, pod:" + p.Name)
	}

	endpointList := make([]*servicev1.ServiceEndpoint, 0)
	var err error = nil

	if lrcConfig != nil {
		lrcSvc := lrcConfig.Spec.AtlasApplicationName
		if p.IP == "" {
			metrics.UpdatePodRegisterStatus(p.Namespace, p.Name, lrcSvc, metrics.PodRegisterStatusEmptyAddress)
			err = multierr.Append(err, errors.New("empty address found for endpoint, svc: "+lrcSvc))
			return endpointList, err
		}

		for _, portConfig := range lrcConfig.Spec.Ports {
			endpoint := &servicev1.ServiceEndpoint{}
			endpoint.Service = wrapperspb.String(lrcSvc)
			endpoint.Id = wrapperspb.String(fmt.Sprintf("%s/%s/%s", p.NodeName, p.Name, containerStatus.Name))
			endpoint.Port = wrapperspb.UInt32(uint32(portConfig.ContainerPort))
			endpoint.Address = wrapperspb.String(p.IP)
			endpoint.Tags = p.labelsToTags(containerStatus.Name)
			endpoint.Tags = append(endpoint.Tags, "kubernetes")
			sort.Strings(endpoint.Tags)
			meta, err1 := p.toEndpointMeta(podServiceNames, true)
			if err1 != nil {
				metrics.UpdatePodRegisterStatus(p.Namespace, p.Name, lrcSvc, metrics.PodRegisterStatusEndpointMetaError)
				err = multierr.Append(err, errors.New("failed to toEndpointMeta, svc: "+lrcSvc+": "+err1.Error()))
				continue
			}
			// Copy the meta to the endpoint
			log.Debug().Msgf("LRC Metadata: %#v", lrcConfig.Spec.TargetLabels)
			if lrcConfig.Spec.TargetLabels != nil {
				for k, v := range lrcConfig.Spec.TargetLabels {
					meta[fmt.Sprintf("envoy.lb.%s", k)] = v
				}
				meta["envoy.lb.port"] = fmt.Sprintf("%d/%s", portConfig.ContainerPort, portConfig.Protocol)
				if _, found := lrcConfig.Spec.TargetLabels["role"]; !found {
					meta["envoy.lb.role"] = "primary"
				}
			} else {
				meta["envoy.lb.role"] = "primary"
			}
			// Include LRC ResourceVersion in hash to ensure re-registration on any LRC update
			meta["lrc.resource"] = lrcConfig.Namespace + "/" + lrcConfig.Name + ":" + lrcConfig.ResourceVersion
			// Mark multi-entity endpoints in the payload so proton can dual-write
			// their health status to the secondary etcd.
			if checkMultiEntityAnnotationForPodInfo(p) || checkUnifiedAnnotationForLRC(lrcConfig) {
				meta[utils.MultiEntityMetaKey] = utils.MultiEntityMetaValue
			}
			endpoint.Meta = meta
			endpoint.HealthStatus = healthStatus

			// Resolve the health check. If a probe is configured but its port
			// name cannot be resolved, probeToEtcdCheck returns nil -- skip
			// registering this endpoint rather than publishing a broken check.
			if probe := p.prepareUnifiedHealthCheckProbe(containerStatus.Name); probe != nil {
				check := p.probeToEtcdCheck(probe, utils.UnifiedHealthCheckProbeName)
				if check == nil {
					metrics.UpdatePodRegisterStatus(p.Namespace, p.Name, lrcSvc, metrics.PodRegisterStatusProbeUnresolvable)
					err = multierr.Append(err, errors.New("health check unresolvable, skipping registration, svc: "+lrcSvc))
					continue
				}
				// No target means no port could be resolved for this
				// container's probe. Register the endpoint without a check
				// rather than with one that can never connect. Scoped to this
				// container: siblings whose probes resolve keep their checks.
				if !hasTarget(check) {
					metrics.UpdatePodRegisterStatus(p.Namespace, p.Name, lrcSvc, metrics.PodRegisterStatusProbeNoPort)
				} else {
					endpoint.HealthChecks = append(endpoint.HealthChecks, check)
				}
			}

			log.Debug().Msgf("PodToEtcdService: Formed Etcd service: %#v", endpoint)
			_, err2 := validate.ValidateServiceEndpoint(endpoint)
			if err2 != nil {
				err = multierr.Append(err, err2)
				metrics.UpdatePodRegisterStatus(p.Namespace, p.Name, lrcSvc, metrics.PodRegisterStatusValidationFailed)
				continue
			}

			data, err3 := proto.MarshalOptions{Deterministic: true}.Marshal(endpoint)
			if err3 != nil {
				metrics.UpdatePodRegisterStatus(p.Namespace, p.Name, lrcSvc, metrics.PodRegisterStatusMarshalFailed)
				err = multierr.Append(err, err3)
				continue
			}
			endpoint.Version = wrapperspb.String(utils.HashResource(data))
			log.Trace().Msgf("Pod: %s, Version: %s, StringBytes: %s, Bytes: %v", p.Name, endpoint.Version.GetValue(), string(data), data)
			endpointList = append(endpointList, endpoint)
		}
		// Dual-registration fall-through: getServiceNameFromPod resolves legacy
		// names beyond the LRC name only when dual-write applies — for relaxed
		// LRCs when the pod's annotation/K8s-Service name DIFFERS from the LRC
		// application name, for non-relaxed LRCs when allow-dual-registration
		// is set. The LRC loop above only wrote endpoints under lrcSvc;
		// continue to the annotation loop so the extra names get their own
		// service-keyed etcd entries. The annotation loop skips lrcSvc, so a
		// matching legacy name registers via the LRC way only.
		dualWrite := false
		for _, svc := range podServiceNames {
			if svc != lrcSvc {
				dualWrite = true
				break
			}
		}
		if !dualWrite {
			// All resolved names collapse into the LRC name — LRC-exclusive
			// registration, do not run the annotation loop.
			return endpointList, err
		}
		log.Debug().
			Str("pod", p.Name).
			Str("namespace", p.Namespace).
			Str("lrcSvc", lrcSvc).
			Strs("podServiceNames", podServiceNames).
			Msg("PodToEtcdServiceEndpoint: dual-write fall-through to annotation loop for non-LRC names")
	}
	for _, svc := range podServiceNames {
		// Skip the LRC service name during dual-write fall-through — it was
		// already handled by the LRC loop above using lrcConfig.Spec.Ports.
		if lrcConfig != nil && svc == lrcConfig.Spec.AtlasApplicationName {
			continue
		}
		endpoint := &servicev1.ServiceEndpoint{}
		endpoint.Service = wrapperspb.String(svc)
		endpoint.Id = wrapperspb.String(fmt.Sprintf("%s/%s/%s", p.NodeName, p.Name, containerStatus.Name))
		port := p.getContainerPort(containerStatus.Name)
		if port == 0 {
			metrics.UpdatePodRegisterStatus(p.Namespace, p.Name, svc, metrics.PodRegisterStatusPortZero)
			err = multierr.Append(err, errors.New("port's equal to 0, svc: "+svc))
			continue
		}
		endpoint.Port = wrapperspb.UInt32(uint32(port))
		if p.IP == "" {
			metrics.UpdatePodRegisterStatus(p.Namespace, p.Name, svc, metrics.PodRegisterStatusEmptyAddress)
			err = multierr.Append(err, errors.New("empty address found for endpoint, svc: "+svc))
			continue
		}
		endpoint.Address = wrapperspb.String(p.IP)
		endpoint.Tags = p.labelsToTags(containerStatus.Name)
		endpoint.Tags = append(endpoint.Tags, "kubernetes")
		sort.Strings(endpoint.Tags)
		meta, err1 := p.toEndpointMeta(podServiceNames, false)
		if err1 != nil {
			metrics.UpdatePodRegisterStatus(p.Namespace, p.Name, svc, metrics.PodRegisterStatusEndpointMetaError)
			err = multierr.Append(err, errors.New("failed to toEndpointMeta, svc: "+svc+": "+err1.Error()))
			continue
		}
		endpoint.Meta = meta
		meta["envoy.lb.role"] = "primary"
		// Mark multi-entity endpoints in the payload so proton can dual-write
		// their health status to the secondary etcd.
		if checkMultiEntityAnnotationForPodInfo(p) || checkUnifiedAnnotationForLRC(lrcConfig) {
			meta[utils.MultiEntityMetaKey] = utils.MultiEntityMetaValue
		}
		endpoint.HealthStatus = healthStatus

		// Resolve the health check. If a probe is configured but its port
		// name cannot be resolved, probeToEtcdCheck returns nil -- skip
		// registering this endpoint rather than publishing a broken check.
		if probe := p.prepareUnifiedHealthCheckProbe(containerStatus.Name); probe != nil {
			check := p.probeToEtcdCheck(probe, utils.UnifiedHealthCheckProbeName)
			if check == nil {
				metrics.UpdatePodRegisterStatus(p.Namespace, p.Name, svc, metrics.PodRegisterStatusProbeUnresolvable)
				err = multierr.Append(err, errors.New("health check unresolvable, skipping registration, svc: "+svc))
				continue
			}
			// No target means no port could be resolved for this container's
			// probe. Register the endpoint without a check rather than with
			// one that can never connect. Scoped to this container: siblings
			// whose probes resolve keep their checks.
			if !hasTarget(check) {
				metrics.UpdatePodRegisterStatus(p.Namespace, p.Name, svc, metrics.PodRegisterStatusProbeNoPort)
			} else {
				endpoint.HealthChecks = append(endpoint.HealthChecks, check)
			}
		}

		log.Debug().Msgf("PodToEtcdService: Formed Etcd service: %#v", endpoint)
		_, err2 := validate.ValidateServiceEndpoint(endpoint)
		if err2 != nil {
			err = multierr.Append(err, err2)
			metrics.UpdatePodRegisterStatus(p.Namespace, p.Name, svc, metrics.PodRegisterStatusValidationFailed)
			continue
		}

		data, err3 := proto.MarshalOptions{Deterministic: true}.Marshal(endpoint)
		if err3 != nil {
			metrics.UpdatePodRegisterStatus(p.Namespace, p.Name, svc, metrics.PodRegisterStatusMarshalFailed)
			err = multierr.Append(err, err3)
			continue
		}
		endpoint.Version = wrapperspb.String(utils.HashResource(data))
		log.Trace().Msgf("Pod: %s, Version: %s, StringBytes: %s, Bytes: %v", p.Name, endpoint.Version.GetValue(), string(data), data)
		endpointList = append(endpointList, endpoint)
	}

	if len(endpointList) == 0 {
		err = multierr.Append(err, errors.New("no valid endpoints found, pod:"+p.Name))
		return nil, err
	}

	return endpointList, err
}

func toServiceID(endpoint *servicev1.ServiceEndpoint) (string, error) {
	_, err := validate.ValidateServiceEndpoint(endpoint)
	if err != nil {
		log.Error().Dict("custom_attributes", logger.Attrs().
			Str("status_code", string(logger.GALACTUS_ETCD_VALIDATION_FAILED)).
			Str("service", endpoint.Service.GetValue()).
			Str("error", err.Error())).
			Msg("Failed to validate service endpoint")
		return "", err
	}
	service := endpoint.Service.GetValue()
	id := endpoint.Id.GetValue()
	return fmt.Sprintf("%s/%s", service, id), nil
}

